"use client";

import * as React from "react";
import { Menu as DropdownMenuPrimitive } from "@base-ui/react/menu";

import { cn } from "@/lib/utils";
import { menuItemBase, popoverSurface, popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<Props> = Omit<Props, "className"> & { className?: string };

type PositionerProps = Pick<
  DropdownMenuPrimitive.Positioner.Props,
  "align" | "alignOffset" | "side" | "sideOffset"
>;

/** The menu panel: the white card with the olive hairline, at least 12rem wide. */
const menuPanel = cn(
  popoverSurface,
  popupMotion,
  "min-w-48 max-h-(--available-height) overflow-y-auto p-1",
);

/** Playful console DropdownMenu root: a list of actions behind one trigger. */
const DropdownMenu = DropdownMenuPrimitive.Root;

/** The control the menu opens from. */
const DropdownMenuTrigger = DropdownMenuPrimitive.Trigger;

/** Groups related rows, and gives a label something to name. */
const DropdownMenuGroup = DropdownMenuPrimitive.Group;

/** Moves a menu panel to the end of the document body. */
const DropdownMenuPortal = DropdownMenuPrimitive.Portal;

/** Wraps a nested menu: its sub-trigger and its sub-content. */
const DropdownMenuSub = DropdownMenuPrimitive.SubmenuRoot;

/** Holds a set of radio rows where only one can be chosen. */
const DropdownMenuRadioGroup = DropdownMenuPrimitive.RadioGroup;

/**
 * The dropdown menu panel: a white card with the olive hairline and a soft
 * drop. It grows from the trigger and fades in.
 */
function DropdownMenuContent({
  className,
  align = "start",
  alignOffset,
  side,
  sideOffset = 6,
  ...props
}: WithClassName<DropdownMenuPrimitive.Popup.Props> & PositionerProps) {
  return (
    <DropdownMenuPrimitive.Portal>
      <DropdownMenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <DropdownMenuPrimitive.Popup
          data-slot="dropdown-menu-content"
          className={cn(menuPanel, className)}
          {...props}
        />
      </DropdownMenuPrimitive.Positioner>
    </DropdownMenuPrimitive.Portal>
  );
}
DropdownMenuContent.displayName = "DropdownMenuContent";

/** A nested menu panel. It opens beside its row, level with the row's top. */
function DropdownMenuSubContent({
  className,
  align = "start",
  alignOffset = -4,
  side = "right",
  sideOffset = 2,
  ...props
}: WithClassName<DropdownMenuPrimitive.Popup.Props> & PositionerProps) {
  return (
    <DropdownMenuPrimitive.Portal>
      <DropdownMenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <DropdownMenuPrimitive.Popup
          data-slot="dropdown-menu-sub-content"
          className={cn(menuPanel, className)}
          {...props}
        />
      </DropdownMenuPrimitive.Positioner>
    </DropdownMenuPrimitive.Portal>
  );
}
DropdownMenuSubContent.displayName = "DropdownMenuSubContent";

/**
 * A menu row with a 0.25rem corner that takes a cream wash under the pointer
 * or keyboard. The destructive variant turns the text red on a red tint.
 */
function DropdownMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: WithClassName<DropdownMenuPrimitive.Item.Props> & {
  inset?: boolean;
  variant?: "default" | "destructive";
}) {
  return (
    <DropdownMenuPrimitive.Item
      data-slot="dropdown-menu-item"
      data-variant={variant}
      className={cn(
        menuItemBase,
        "[&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground",
        variant === "destructive" &&
          "text-(--destructive-text) data-[highlighted]:bg-(--destructive-tint) data-[highlighted]:text-(--destructive-text) [&_svg]:text-(--destructive-text)",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}
DropdownMenuItem.displayName = "DropdownMenuItem";

/** A row that opens a nested menu, with a caret at the end. */
function DropdownMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: WithClassName<DropdownMenuPrimitive.SubmenuTrigger.Props> & {
  inset?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.SubmenuTrigger
      data-slot="dropdown-menu-sub-trigger"
      className={cn(
        menuItemBase,
        "data-[popup-open]:bg-accent data-[popup-open]:text-accent-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    >
      {children}
      <ChevronRightIcon
        className="ms-auto size-3.5 text-muted-foreground rtl:rotate-180"
        aria-hidden="true"
      />
    </DropdownMenuPrimitive.SubmenuTrigger>
  );
}
DropdownMenuSubTrigger.displayName = "DropdownMenuSubTrigger";

/** A row that toggles on and off. A small orange key with a tick sits at the end when on. */
function DropdownMenuCheckboxItem({
  className,
  children,
  ...props
}: WithClassName<DropdownMenuPrimitive.CheckboxItem.Props>) {
  return (
    <DropdownMenuPrimitive.CheckboxItem
      data-slot="dropdown-menu-checkbox-item"
      className={cn(menuItemBase, "pe-8", className)}
      {...props}
    >
      {children}
      <span className="pointer-events-none absolute end-2 flex size-4 items-center justify-center">
        <DropdownMenuPrimitive.CheckboxItemIndicator className="flex size-4 items-center justify-center rounded-md border border-(--primary-rim) bg-primary text-primary-foreground">
          <CheckIcon className="size-2.5" aria-hidden="true" />
        </DropdownMenuPrimitive.CheckboxItemIndicator>
      </span>
    </DropdownMenuPrimitive.CheckboxItem>
  );
}
DropdownMenuCheckboxItem.displayName = "DropdownMenuCheckboxItem";

/** One choice in a radio group. An orange dot with its rim sits at the end when chosen. */
function DropdownMenuRadioItem({
  className,
  children,
  ...props
}: WithClassName<DropdownMenuPrimitive.RadioItem.Props>) {
  return (
    <DropdownMenuPrimitive.RadioItem
      data-slot="dropdown-menu-radio-item"
      className={cn(menuItemBase, "pe-8", className)}
      {...props}
    >
      {children}
      <span className="pointer-events-none absolute end-2 flex size-4 items-center justify-center">
        <DropdownMenuPrimitive.RadioItemIndicator>
          <span className="block size-2.5 rounded-full border border-(--primary-rim) bg-primary" />
        </DropdownMenuPrimitive.RadioItemIndicator>
      </span>
    </DropdownMenuPrimitive.RadioItem>
  );
}
DropdownMenuRadioItem.displayName = "DropdownMenuRadioItem";

/** A small bold uppercase heading over a group of rows. Use it inside a group. */
function DropdownMenuLabel({
  className,
  inset,
  ...props
}: WithClassName<DropdownMenuPrimitive.GroupLabel.Props> & {
  inset?: boolean;
}) {
  return (
    <DropdownMenuPrimitive.GroupLabel
      data-slot="dropdown-menu-label"
      className={cn(
        "px-2.5 py-1.5 text-xs font-bold uppercase text-muted-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}
DropdownMenuLabel.displayName = "DropdownMenuLabel";

/** A soft line between groups that runs to the panel's edges. */
function DropdownMenuSeparator({
  className,
  ...props
}: WithClassName<DropdownMenuPrimitive.Separator.Props>) {
  return (
    <DropdownMenuPrimitive.Separator
      data-slot="dropdown-menu-separator"
      className={cn("-mx-1 my-1 h-px bg-(--line-soft)", className)}
      {...props}
    />
  );
}
DropdownMenuSeparator.displayName = "DropdownMenuSeparator";

/** The keyboard shortcut at the end of a row, in small mono type. */
function DropdownMenuShortcut({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn("ms-auto ps-4 font-mono text-xs text-muted-foreground", className)}
      {...props}
    />
  );
}
DropdownMenuShortcut.displayName = "DropdownMenuShortcut";

export {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuCheckboxItem,
  DropdownMenuRadioItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuGroup,
  DropdownMenuPortal,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuRadioGroup,
};

// Phosphor, the icon library this system pairs with, drawn inline
// so the installed component loads no icon at runtime:
// "ph:check-bold" "ph:caret-right-bold"
// [BD-1029]
function CheckIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 256 256" aria-hidden="true" {...props}>
      <path fill="currentColor" d="m232.49 80.49l-128 128a12 12 0 0 1-17 0l-56-56a12 12 0 1 1 17-17L96 183L215.51 63.51a12 12 0 0 1 17 17Z"/>
    </svg>
  );
}
function ChevronRightIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 256 256" aria-hidden="true" {...props}>
      <path fill="currentColor" d="m184.49 136.49l-80 80a12 12 0 0 1-17-17L159 128L87.51 56.49a12 12 0 1 1 17-17l80 80a12 12 0 0 1-.02 17"/>
    </svg>
  );
}
